  asYears: fc.boolean(),
})

/** Amounts spread over every order of magnitude from 10 to 10^15. */
const wideCents = fc.oneof(
  fc.bigInt({ min: AMOUNT_MIN_CENTS, max: AMOUNT_MAX_CENTS }),
